            "doc": "\nThe MeasurementManager class provides some generic measurement utilities that\ncan be used for most entity types.\n",
            "functions": [
                {
                    "doc": "Calculates an oriented bounding box for the input geometry",
                    "name": "getOrientedBoundingBox"
                },
                {
                    "doc": "Measures the minimum distance between the two input geometries",
                    "name": "measureMinimumDistance"
                },
                {
                    "doc": "Measures the angle between the input geometry",
                    "name": "measureAngle"
                }
            ],
            "name": "MeasureManager",
            "namespace": "adsk.core",
            "type": "class"
        },
        {
            "doc": "Represents a B-Rep (Boundary Representation) body.",
            "functions": [
                {
                    "doc": "Determines the relationship of the input point with respect to this body",
                    "name": "pointContainment"
                },
                {
                    "doc": "Deletes the body",
                    "name": "deleteMe"
                },
                {
                    "doc": "Copies the body to the clipboard",
                    "name": "copy"
                },
                {
                    "doc": "Cuts the body to the clipboard",
                    "name": "cut"
                },
                {
                    "doc": "Returns a proxy for the native object\n- i",
                    "name": "createForAssemblyContext"
                },
                {
                    "doc": "Creates a new component and occurrence within the component that currently owns this body",
                    "name": "createComponent"
                },
                {
                    "doc": "Moves this body from its current component into the root component or the component owned by the\nspecified occurrence",
                    "name": "moveToComponent"
                },
                {
                    "doc": "Creates a copy of this body into the specified target",
                    "name": "copyToComponent"
                },
                {
                    "doc": "Creates a new body where the faces and edges are converted to different\ntypes of geometry based on the input options",
                    "name": "convert"
                },
                {
                    "doc": "Returns all of the faces, edges, or vertices that match the input ID",
                    "name": "findByTempId"
                },
                {
                    "doc": "Returns the PhysicalProperties object that has properties for getting the area, density, mass, volume, moments, etc\nof this body",
                    "name": "getPhysicalProperties"
                },
                {
                    "doc": "Finds the thickness of the body at the specified face by casting a ray from the\nface along its inward normal and measuring the distance to the first opposite\nface of the body that is hit",
                    "name": "findThicknessAtFace"
                },
                {
                    "doc": "Converts the current BRepBody to a sheet metal body",
                    "name": "convertToSheetMetal"
                }
            ],
            "name": "BRepBody",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Returns the component this body is owned by",
                    "name": "parentComponent"
                },
                {
                    "doc": "Returns a collection of all of the lumps in the body",
                    "name": "lumps"
                },
                {
                    "doc": "Returns a collection of all of the shells in the body",
                    "name": "shells"
                },
                {
                    "doc": "Returns a collection of all of the faces in the body",
                    "name": "faces"
                },
                {
                    "doc": "Returns a collection of all of the edges in the body",
                    "name": "edges"
                },
                {
                    "doc": "Returns a collection of all of the vertices in the body",
                    "name": "vertices"
                },
                {
                    "doc": "Returns whether this body is closed (solid) or not",
                    "name": "isSolid"
                },
                {
                    "doc": "Returns the bounding box of this body",
                    "name": "boundingBox"
                },
                {
                    "doc": "Returns all of the edges that connect concave faces",
                    "name": "concaveEdges"
                },
                {
                    "doc": "Returns all of the edges that connect convex faces",
                    "name": "convexEdges"
                },
                {
                    "doc": "Returns the area in cm ^ 2",
                    "name": "area"
                },
                {
                    "doc": "Returns the volume in cm ^ 3",
                    "name": "volume"
                },
                {
                    "doc": "Indicates if this body is represented in the model or is transient",
                    "name": "isTransient"
                },
                {
                    "doc": "Gets and sets the name of the body",
                    "name": "name"
                },
                {
                    "doc": "Gets if this body is currently visible in the graphics window",
                    "name": "isVisible"
                },
                {
                    "doc": "Gets and sets if this body is selectable",
                    "name": "isSelectable"
                },
                {
                    "doc": "Read-write property that gets and sets the current appearance of the body",
                    "name": "appearance"
                },
                {
                    "doc": "Read-write property that gets the source of the appearance for the body",
                    "name": "appearanceSourceType"
                },
                {
                    "doc": "Gets and sets the material assigned to this body",
                    "name": "material"
                },
                {
                    "doc": "Returns the mesh manager object for this body",
                    "name": "meshManager"
                },
                {
                    "doc": "Returns the assembly occurrence (i",
                    "name": "assemblyContext"
                },
                {
                    "doc": "The NativeObject is the object outside the context of an assembly",
                    "name": "nativeObject"
                },
                {
                    "doc": "Returns the PhysicalProperties object that has properties for getting the area, density, mass, volume, moments, etc\nof this body",
                    "name": "physicalProperties"
                },
                {
                    "doc": "Gets and sets if the light bulb beside the body node in the\nbrowser is on or not",
                    "name": "isLightBulbOn"
                },
                {
                    "doc": "Returns the collection of attributes associated with this face",
                    "name": "attributes"
                },
                {
                    "doc": "If this body is associated with a base feature, this property will return that base feature",
                    "name": "baseFeature"
                },
                {
                    "doc": "Gets and sets the opacity override assigned to this body",
                    "name": "opacity"
                },
                {
                    "doc": "The user can set an override opacity for components and bodies",
                    "name": "visibleOpacity"
                },
                {
                    "doc": "Returns the current revision ID of the body",
                    "name": "revisionId"
                },
                {
                    "doc": "Returns any wire bodies that exist within this body",
                    "name": "wires"
                },
                {
                    "doc": "Indicates if this body is represented in the model or is temporary",
                    "name": "isTemporary"
                },
                {
                    "doc": "Returns a token for the BRepBody object",
                    "name": "entityToken"
                },
                {
                    "doc": "Returns the TextureMapControl object associated with this body when there is an\nappearance assigned to the body that has a texture associated with it",
                    "name": "textureMapControl"
                },
                {
                    "doc": "Indicates if this body represents a sheet metal folded part or not and if a flat pattern can be created",
                    "name": "isSheetMetal"
                },
                {
                    "doc": "Returns an oriented bounding box of the body that is best oriented to tightly fit the body",
                    "name": "orientedMinimumBoundingBox"
                },
                {
                    "doc": "Returns a bounding box that tightly fits this body",
                    "name": "preciseBoundingBox"
                },
                {
                    "doc": "Returns if this BRepBody is derived from another design",
                    "name": "isDerived"
                },
                {
                    "doc": "Returns the DeriveFeature if this BRepBody is derived from another design",
                    "name": "deriveFeature"
                }
            ],
            "type": "class"
        },
        {
            "doc": "\nA utility object that provides functionality to create and manipulate B-Rep data outside\nthe context of a document. The provides direct access to the modeling core without the\noverhead of parametrics, persistence, transactions, or graphics. It also provides a way\nof directly defining and creating B-Rep data.\n",
            "functions": [
                {
                    "doc": "Creates a temporary copy of the input BRepBody, BRepFace, or BRepEdge object",
                    "name": "copy"
                },
                {
                    "doc": "Calculates the intersection between the input body and plane and creates a\nwire body that represents the intersection curves",
                    "name": "planeIntersection"
                },
                {
                    "doc": "Creates a new body by creating a ruled surface between the two input wire bodies",
                    "name": "createRuledSurface"
                },
                {
                    "doc": "Calculates the silhouette curve geometry for a given face as viewed from a given direction",
                    "name": "createSilhouetteCurves"
                },
                {
                    "doc": "Deletes one or more faces from a temporary BRepBody",
                    "name": "deleteFaces"
                },
                {
                    "doc": "Performs the specified Boolean operation between the two input bodies",
                    "name": "booleanOperation"
                },
                {
                    "doc": "Transforms the input body using the specified transformation matrix",
                    "name": "transform"
                },
                {
                    "doc": "Creates new BRepBody objects based on the contents of the specified file",
                    "name": "createFromFile"
                },
                {
                    "doc": "Exports the input bodies to the specified file",
                    "name": "exportToFile"
                },
                {
                    "doc": "Creates a new temporary solid box BRepBody object",
                    "name": "createBox"
                },
                {
                    "doc": "Creates a temporary solid cylinder or cone BRepBody object",
                    "name": "createCylinderOrCone"
                },
                {
                    "doc": "Creates a temporary elliptical solid cylinder or cone BRepBody object",
                    "name": "createEllipticalCylinderOrCone"
                },
                {
                    "doc": "Creates a temporary spherical BRepBody object",
                    "name": "createSphere"
                },
                {
                    "doc": "Creates a temporary toroidal BRepBody object",
                    "name": "createTorus"
                },
                {
                    "doc": "Creates a body from multiple wires that all lie within the same plane",
                    "name": "createFaceFromPlanarWires"
                },
                {
                    "doc": "Method that finds regions of faces on two bodies which overlap and creates new bodies where the faces\nare split at the edges of the overlaps",
                    "name": "imprintOverlapBodies"
                },
                {
                    "doc": "Give an array of curve geometry objects, this method creates a new wire body",
                    "name": "createWireFromCurves"
                },
                {
                    "doc": "Creates a B-Rep body that contains a wire with a single edge that represents a helical curve",
                    "name": "createHelixWire"
                },
                {
                    "doc": "Computes the approximate outline of a body",
                    "name": "createProjectedBodyOutline"
                }
            ],
            "name": "TemporaryBRepManager",
            "namespace": "adsk.fusion",
            "staticmethods": [
                {
                    "doc": "Gets the TempoaryBRepManager object",
                    "name": "get"
                }
            ],
            "type": "class"
        },
