        {
            "doc": "\nThis object is used to define a temporary B-Rep body. This includes solid, surface, and wire\nbodies. The class supports the ability to define the geometry and topology of the B-Rep and\nonce the definition is complete, it supports the creation of a temporary BRepBody object.\n",
            "functions": [
                {
                    "doc": "Attempts to create a temporary BRepBody object using the definition\nprovided by this BRepBodyDefinition object",
                    "name": "createBody"
                },
                {
                    "doc": "Using a curve in model space it creates a new BRepEdgeDefinition object that's associated with the body",
                    "name": "createEdgeDefinitionByCurve"
                },
                {
                    "doc": "Creates a new BRepVertexDefinition object that's associated with the body",
                    "name": "createVertexDefinition"
                }
            ],
            "name": "BRepBodyDefinition",
            "namespace": "adsk.fusion",
            "properties": [
                {
                    "doc": "Specifies if full healing is done when creating the body",
                    "name": "doFullHealing"
                },
                {
                    "doc": "Returns an array of strings that contain information about the outcome of the previous\ncall of the createBody method",
                    "name": "outcomeInfo"
                },
                {
                    "doc": "Provides access to the BRepLumpDefinitions object associated with this BRepBodyDefinition",
                    "name": "lumpDefinitions"
                }
            ],
            "staticmethods": [
